import{z as i,x as s,o as r,c,q as B,j as n,D as E,d as e,s as o,S as l,b as t}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"利率交易策略","description":"","frontmatter":{"title":"利率交易策略","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/mac-rates-strategies.md","filePath":"quant/mac-rates-strategies.md","lastUpdated":1791063341000}'),d={name:"quant/mac-rates-strategies.md"};function p(D,a,u,m,h,f){const A=s("Mermaid");return r(),c("div",null,[a[2]||(a[2]=B('<h1 id="利率交易策略" tabindex="-1">利率交易策略 <a class="header-anchor" href="#利率交易策略" aria-label="Permalink to &quot;利率交易策略&quot;">​</a></h1><div class="epigraph"><p>债券收益的共同来源比债券的个数少得多：水平、斜率、曲率。观点若不声明自己在交易哪根轴，账户会替你随机选一根。</p><footer>—— 据 Litterman &amp; Scheinkman, Journal of Fixed Income, 1991 与 Koijen, Moskowitz, Pedersen &amp; Vrugt, JFE, 2018 整理</footer></div><p><a href="/quant/mac-tactical-allocation">上一课</a>把多路信号收进围绕政策组合的有界偏离，并要求每个信号先折成方向与强度。象限表里「衰退买久期、过热缩久期」在那里还是一行映射；本课把它落成可成交的利率头寸：观点沿哪根轴、用什么工具表达、carry 与对冲怎么算、盈亏记在哪一层。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>宏观观点与利率头寸之间隔着三个不对齐。第一，收益率曲线不是一维：水平、斜率、曲率解释了大部分共同变动（<a href="/quant/curve-pca">曲线主成分</a>），「看空利率」的仓在斜率与曲率上多半背着未被声明的暴露，跌对了方向也可能亏钱。第二，观点是预期，头寸盈亏是 carry 与变动之和：正 carry 是缓冲不是信号，把它当做多理由，方向错时的亏损只会比直觉更大、更慢显现。第三，工具不是中性选择：现券、期货与互换的 carry、保证金与基差各不相同，同一观点换工具等于换策略。缺口是把每个宏观观点分解成对三根轴的显式声明，再让工具服从分解。</p><p><span class="marginnote">「DV01」翻译成白话：收益率变动 1 个基点（0.01%）时头寸盈亏多少钱。久期约 5、面值 100 万的债券，DV01 约 500 美元——收益率上行 10bp 就亏约 5000 美元。它是利率头寸「刻度每格对应多少钱」的读数。</span></p><h3 id="三族头寸与-carry-分解" tabindex="-1">三族头寸与 carry 分解 <a class="header-anchor" href="#三族头寸与-carry-分解" aria-label="Permalink to &quot;三族头寸与 carry 分解&quot;">​</a></h3><p>三根轴各对应一族头寸：纯久期对水平，DV01 中性的陡峭化与平坦化对斜率，两翼对中间的蝶式对曲率——蝶式权重由关键期限 DV01 解出，不是固定的 \\(1:-2:1\\)（<a href="/quant/curve-butterfly">曲线蝶式</a>）。持有期期望超额按期限结构 carry 分解（<a href="/quant/ts-carry">期限结构 carry</a>）：价格不变假设下的 carry 加 roll-down 是相对确定的部分，方向判断只作用于 DV01 乘期望收益率变动那一项；把四项混成一句「看多债券」，归因就无从谈起。</p><p><span class="marginnote">1994 年 2 月起美联储一年内连续加息 250 个基点，10 年期美债收益率上行约 200bp；靠回购杠杆放大久期的橙郡（Orange County）组合当年 12 月破产。carry 厚度不覆盖 DV01×Δy，杠杆把这句话变成偿付问题。</span></p><p><span class="marginnote">做陡、做平与蝶式可以想成调一块可弯的尺子：做陡是把右端相对左端抬高（赌长短利差变大）；做平相反；蝶式是压中间、抬两头（或反过来），赌曲线的「肚子」变瘪还是变鼓。三者都把水平方向对冲掉，只留形状暴露。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>宏观映射沿象限走：衰退格与宽松初期做多久期、做陡；过热格与加息周期尾端缩久期、付固定、做平——斜率由央行路径主导，反应函数变了格序跟着变（第二课的边界在利率上的投影）。执行分三步。第一步选工具：期货要盯 CTD 切换与净基差；互换要认出<a href="/quant/swap-spread">互换价差</a>里混入的信用与监管供需，并按<a href="/quant/multi-curve-ois">多曲线</a>口径记账折现。第二步对冲：非平行观点用<a href="/quant/key-rate-duration">关键利率久期</a>在关键工具上解向量，久期长的头寸补<a href="/quant/duration-convexity">凸性</a>修正。第三步风控：期货保证金与互换变动保证金的现金流错配、新券发行与拍卖日历、央行会议与数据日的日历风险，分别设限。</p>',12)),(r(),n(l,null,{default:E(()=>[o(A,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20V%5B%22%E5%AE%8F%E8%A7%82%E8%A7%82%E7%82%B9%22%5D%20--%3E%20A%5B%22%E5%A3%B0%E6%98%8E%E4%BA%A4%E6%98%93%E5%93%AA%E6%A0%B9%E8%BD%B4%22%5D%0A%20%20A%20--%3E%20L%5B%22%E6%B0%B4%E5%B9%B3%EF%BC%9A%E7%BA%AF%E4%B9%85%E6%9C%9F%22%5D%0A%20%20A%20--%3E%20S%5B%22%E6%96%9C%E7%8E%87%EF%BC%9A%E9%99%A1%E5%B3%AD%2F%E5%B9%B3%E5%9D%A6%EF%BC%8CDV01%20%E4%B8%AD%E6%80%A7%22%5D%0A%20%20A%20--%3E%20C%5B%22%E6%9B%B2%E7%8E%87%EF%BC%9A%E8%9D%B6%E5%BC%8F%22%5D%0A%20%20L%20--%3E%20T%5B%22%E5%B7%A5%E5%85%B7%E9%80%89%E6%8B%A9%EF%BC%9A%E7%8E%B0%E5%88%B8%2F%E6%9C%9F%E8%B4%A7%2F%E4%BA%92%E6%8D%A2%22%5D%0A%20%20S%20--%3E%20T%0A%20%20C%20--%3E%20T%0A%20%20T%20--%3E%20H%5B%22KRD%20%E5%AF%B9%E5%86%B2%E4%B8%8E%E5%87%B8%E6%80%A7%E4%BF%AE%E6%AD%A3%22%5D%0A%20%20T%20--%3E%20R%5B%22carry%20%E4%B8%8E%20roll-down%20%E8%AE%B0%E8%B4%A6%22%5D%0A%20%20H%20--%3E%20R%0A%20%20R%20--%3E%20K%5B%22%E4%BF%9D%E8%AF%81%E9%87%91%E3%80%81%E5%9F%BA%E5%B7%AE%E4%B8%8E%E6%97%A5%E5%8E%86%E9%A3%8E%E9%99%A9%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"先拆轴再下单的机制理由：不拆的仓位是三根轴暴露的随机和，事后无法回答「观点错在哪一层」，上一课的偏离归因在这里接不住。carry 分解的机制意义是把确定的与要预测的分开：curve 头寸对掉水平后剩下的斜率暴露，收益主要来自央行路径与期限溢价的移动——正是第一、二课状态变量在利率内部的投影。对冲结构因此随象限变：衰退格里久期与股票负相关，久期仓是组合的对冲腿；滞胀格里两者正相关，同一笔久期只是另一份风险。第二课「换格换分散结构」的论断，在资产内部同样成立。",-1)),(r(),n(l,null,{default:E(()=>[o(A,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20E%5B%22%E6%8C%81%E6%9C%89%E6%9C%9F%E6%9C%9F%E6%9C%9B%E8%B6%85%E9%A2%9D%E6%94%B6%E7%9B%8A%22%5D%20--%3E%20C%5B%22carry%3A%20%E4%BB%B7%E6%A0%BC%E4%B8%8D%E5%8F%98%E4%B8%8B%E7%9A%84%E7%A5%A8%E6%81%AF%E5%B7%AE%22%5D%0A%20%20E%20--%3E%20RD%5B%22roll-down%3A%20%E6%B2%BF%E6%9B%B2%E7%BA%BF%E4%B8%8B%E7%A7%BB%E7%9A%84%E8%B5%84%E6%9C%AC%E5%88%A9%E5%BE%97%22%5D%0A%20%20C%20--%3E%20K%5B%22%E7%9B%B8%E5%AF%B9%E7%A1%AE%E5%AE%9A%E7%9A%84%E9%83%A8%E5%88%86%22%5D%0A%20%20RD%20--%3E%20K%0A%20%20E%20--%3E%20D%5B%22DV01%20%C3%97%20%E6%9C%9F%E6%9C%9B%E6%94%B6%E7%9B%8A%E7%8E%87%E5%8F%98%E5%8A%A8%22%5D%0A%20%20D%20--%3E%20P%5B%22%E9%9C%80%E8%A6%81%E6%96%B9%E5%90%91%E5%88%A4%E6%96%AD%E7%9A%84%E9%83%A8%E5%88%86%22%5D%0A%20%20P%20--%3E%20B%5B%22%E9%94%99%E6%96%B9%E5%90%91%E6%97%B6%E7%9A%84%E4%BA%8F%E6%8D%9F%E6%9D%A5%E6%BA%90%22%5D%0A%20%20K%20--%3E%20G%5B%22%E7%BC%93%E5%86%B2%E5%9E%AB%3A%20%E4%B8%8D%E6%9E%84%E6%88%90%E5%81%9A%E5%A4%9A%E7%90%86%E7%94%B1%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=B('<p><span class="marginnote">常见误区：把「这笔交易 carry 为正」当成看多理由。正 carry 只是每天到账的缓冲垫：方向对它加分，方向错只能让你亏得慢一点。橙郡的教训是杠杆放大 DV01 之后，carry 的厚度根本盖不住收益率上行的亏损。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>久期只对瞬时平行移动成立，扭转让 DV01 中性的曲线仓照样亏损（凸性课的口径）。互换价差不是纯利率：拿它当利率观点的对冲腿，等于把信用与监管供需一起买进组合。央行是利率市场最大的玩家，「按统计规律做平做陡」在反应函数切换点系统性失效——通胀目标制确立前后的样本不能混用（第二课的警告在利率上的重述）。负利率与走廊制度下 roll-down 的几何变形，照搬正利率样本的 carry 厚度会错。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>先声明交易哪根轴：水平、斜率、曲率各有一族头寸与对冲方法。</li><li>carry 加 roll-down 是价格不变下的确定项，方向判断只作用于 DV01×E[Δy]。</li><li>工具不是中性选择：CTD、互换价差、多曲线各自夹带基差与信用成分。</li><li>斜率由央行路径主导，反应函数切换处统计规律失效。</li><li>出处：Litterman &amp; Scheinkman, Journal of Fixed Income, 1991；Koijen 等, JFE, 2018；轴的统计结构见<a href="/quant/curve-pca">曲线主成分</a>，对冲见<a href="/quant/key-rate-duration">关键利率久期</a>。</li></ul>',5))])}const y=i(d,[["render",p]]);export{F as __pageData,y as default};
